import json
with open('/app/resources/treasury_bulletin_1981_04.json', 'r') as f:
    data = json.load(f)

# Find tables with weekly bank positions
pages = data.get('elements', {}).get('pages', [])
for i, page in enumerate(pages[:20]):
    tables = page.get('tables', [])
    if tables:
        for j, table in enumerate(tables):
            if table.get('title') and 'weekly' in str(table.get('title', '')).lower():
                print(f'Page {i}, Table {j}: {table.get(\"title\")}')
"
